    function ValidateField_participante_id(&$Campos_Crit, &$Campos_Falta, &$Campos_Erros)
    {
        global $teste_validade;
        $hasError = false;
      if (isset($this->Field_no_validate['participante_id'])) {
          nm_limpa_numero($this->participante_id, $this->field_config['participante_id']['symbol_grp']) ; 
          return;
      }
      if ($this->participante_id === "" || is_null($this->participante_id))  
      { 
          $this->participante_id = 0;
      } 
      nm_limpa_numero($this->participante_id, $this->field_config['participante_id']['symbol_grp']) ; 
      if ($this->nmgp_opcao == "incluir" || 'validate_participante_id' == $this->NM_ajax_opcao)
      { 
          if ($this->participante_id != '')  
          { 
              $iTestSize = 11;
              if (strlen($this->participante_id) > $iTestSize)  
              { 
                  $hasError = true;
                  $Campos_Crit .= "Participante Id: " . $this->Ini->Nm_lang['lang_errm_size']; 
                  if (!isset($Campos_Erros['participante_id']))
                  {
                      $Campos_Erros['participante_id'] = array();
                  }
                  $Campos_Erros['participante_id'][] = $this->Ini->Nm_lang['lang_errm_size'];
                  if (!isset($this->NM_ajax_info['errList']['participante_id']) || !is_array($this->NM_ajax_info['errList']['participante_id']))
                  {
                      $this->NM_ajax_info['errList']['participante_id'] = array();
                  }
                  $this->NM_ajax_info['errList']['participante_id'][] = $this->Ini->Nm_lang['lang_errm_size'];
              } 
              if ($teste_validade->Valor($this->participante_id, 11, 0, 0, 0, "N") == false)  
              { 
                  $hasError = true;
                  $Campos_Crit .= "Participante Id; " ; 
                  if (!isset($Campos_Erros['participante_id']))
                  {
                      $Campos_Erros['participante_id'] = array();
                  }
                  $Campos_Erros['participante_id'][] = "" . $this->Ini->Nm_lang['lang_errm_ajax_data'] . "";
                  if (!isset($this->NM_ajax_info['errList']['participante_id']) || !is_array($this->NM_ajax_info['errList']['participante_id']))
                  {
                      $this->NM_ajax_info['errList']['participante_id'] = array();
                  }
                  $this->NM_ajax_info['errList']['participante_id'][] = "" . $this->Ini->Nm_lang['lang_errm_ajax_data'] . "";
              } 
          } 
      } 
        if ($hasError) {
            global $sc_seq_vert;
            $fieldName = 'participante_id';
            if (isset($sc_seq_vert) && '' != $sc_seq_vert) {
                $fieldName .= $sc_seq_vert;
            }
            $this->NM_ajax_info['fieldsWithErrors'][] = $fieldName;
        }
    } // ValidateField_participante_id

