      { 
          $guarda_datahora = $this->field_config['part_dt_nasc']['date_format']; 
          if (false !== strpos($guarda_datahora, ';')) $this->field_config['part_dt_nasc']['date_format'] = substr($guarda_datahora, 0, strpos($guarda_datahora, ';'));
          $Format_Data = $this->field_config['part_dt_nasc']['date_format']; 
          nm_limpa_data($Format_Data, $this->field_config['part_dt_nasc']['date_sep']) ; 
          if (trim($this->part_dt_nasc) != "")  
