          if (false !== strpos($guarda_datahora, ';')) $this->field_config['emissao_passaporte']['date_format'] = substr($guarda_datahora, 0, strpos($guarda_datahora, ';'));
          $Format_Data = $this->field_config['emissao_passaporte']['date_format']; 
          nm_limpa_data($Format_Data, $this->field_config['emissao_passaporte']['date_sep']) ; 
          if (trim($this->emissao_passaporte) != "")  
          { 
              $validateTest = $teste_validade->Data($this->emissao_passaporte, $Format_Data, $trab_dt_min, $trab_dt_max);
              if ($validateTest == false)
              { 
                  $hasError = true;
                  $Campos_Crit .= "Emissão Passaporte:; " ; 
