   function ajax_return_values_nacionalidade($bForce = false)
   {
          if ('navigate_form' == $this->NM_ajax_opcao || 'backup_line' == $this->NM_ajax_opcao || (isset($this->nmgp_refresh_fields) && in_array("nacionalidade", $this->nmgp_refresh_fields)) || $bForce)
          {
              $sTmpValue = NM_charset_to_utf8($this->nacionalidade);
              $aLookup = array();
              $this->_tmp_lookup_nacionalidade = $this->nacionalidade;

$aLookup[] = array(form_acompanhantes_rsvp_pack_protect_string('B') => str_replace('<', '&lt;',form_acompanhantes_rsvp_pack_protect_string("Brasileira")));
$aLookup[] = array(form_acompanhantes_rsvp_pack_protect_string('E') => str_replace('<', '&lt;',form_acompanhantes_rsvp_pack_protect_string("Estrangeira")));
$_SESSION['sc_session'][$this->Ini->sc_page]['form_acompanhantes_rsvp']['Lookup_nacionalidade'][] = 'B';
$_SESSION['sc_session'][$this->Ini->sc_page]['form_acompanhantes_rsvp']['Lookup_nacionalidade'][] = 'E';
          $aLookupOrig = $aLookup;
          $sSelComp = "name=\"nacionalidade\"";
          if (isset($this->NM_ajax_info['select_html']['nacionalidade']) && !empty($this->NM_ajax_info['select_html']['nacionalidade']))
          {
              $sSelComp = str_replace('{SC_100PERC_CLASS_INPUT}', $this->classes_100perc_fields['input'], $this->NM_ajax_info['select_html']['nacionalidade']);
          }
          $sLookup = '';
          if (empty($aLookup))
          {
              $aLookup[] = array('' => '');
          }
          foreach ($aLookup as $aOption)
          {
              foreach ($aOption as $sValue => $sLabel)
              {

                  if ($this->nacionalidade == $sValue)
                  {
                      $this->_tmp_lookup_nacionalidade = $sLabel;
                  }

                  $sOpt     = ($sValue !== $sLabel) ? $sValue : $sLabel;
                  $sLookup .= "<option value=\"" . $sOpt . "\">" . $sLabel . "</option>";
              }
          }
          $aLookup  = $sLookup;
          $this->NM_ajax_info['fldList']['nacionalidade'] = array(
                       'row'    => '',
               'type'    => 'select',
               'valList' => array($sTmpValue),
