function dsc_empresa_rsvp_onChange()
{
$_SESSION['scriptcase']['form_acompanhantes_rsvp']['contr_erro'] = 'on';
  
$original_dsc_empresa_rsvp = $this->dsc_empresa_rsvp;
$original_cod_empresa_rsvp = $this->cod_empresa_rsvp;


$sql = "
	SELECT
		empresa_id,
		empresa_fantasia		
	FROM
		empresas_rsvp		
	WHERE	
		empresa_fantasia = ".$this->Db->qstr($this->dsc_empresa_rsvp )."
";
 
      $nm_select = $sql; 
      $_SESSION['scriptcase']['sc_sql_ult_comando'] = $nm_select; 
      $_SESSION['scriptcase']['sc_sql_ult_conexao'] = ''; 
      $this->rs = array();
      if ($SCrx = $this->Db->Execute($nm_select)) 
      { 
          $SCy = 0; 
          $nm_count = $SCrx->FieldCount();
          while (!$SCrx->EOF)
          { 
                 for ($SCx = 0; $SCx < $nm_count; $SCx++)
                 { 
                      $this->rs[$SCy] [$SCx] = $SCrx->fields[$SCx];
                 }
                 $SCy++; 
                 $SCrx->MoveNext();
          } 
          $SCrx->Close();
      } 
      elseif (isset($GLOBALS["NM_ERRO_IBASE"]) && $GLOBALS["NM_ERRO_IBASE"] != 1)  
      { 
          $this->rs = false;
          $this->rs_erro = $this->Db->ErrorMsg();
      } 
	
if (isset($this->rs[0][0])) {
	$this->cod_empresa_rsvp = $this->rs[0][0];
} else {
	$this->dsc_empresa_rsvp  = '';
	$this->cod_empresa_rsvp = $this->rs[0][0];	
	$this->sc_ajax_message ("Empresa não Cadastrda neste Evento!", "Alerta RSVP", "timeout=15");
}



