			$part_nome_substituto  = '';
			$part_cod_substituto  = '';
			$guarda_cod_substituto  = '';
		} else {
			if($this->external_status  <> 'confirmed') {				
				if($this->external_id  <> '') {
					$token = $this->getTokenApp();
					$curl = curl_init();
					curl_setopt_array($curl, array(
						CURLOPT_URL => 'https://api.beinvited.com.br/backoffice-api/guests/'.$this->id_participante_app ,
						CURLOPT_RETURNTRANSFER => true,
						CURLOPT_ENCODING => '',
