							  CURLOPT_HTTPHEADER => array(
								 'Authorization: Bearer '.$token
							  ),
							));
							$response = curl_exec($curl);
							$httpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
							curl_close($curl);
							if ($httpCode >= 200 && $httpCode < 300) {						
								$this->sc_ajax_message ("O Convidado/Participante foi excluído na API!", "Alerta BRSVP", "timeout=30");			
							} else {
								$this->sc_ajax_message ("O Convidado/Participante não foi excluído na API!", "Alerta BRSVP", "timeout=30");
							}							
						} else {
							$this->sc_ajax_message ("O Status do Convidado/Participante é diferente de pendente na API, não pode ser substituído.", "Alerta BRSVP", "timeout=30");
						}					
					}	
				}
				$this->part_cod_substituido  = $cpf_substituido;
				$this->part_nome_substituido  = $nome_substituido;
				$this->part_empresa  = $empresa_substituido;
				$this->part_id_evento_publico  = $publico_substituido;
				
			} else {
				$this->sc_ajax_message ("O Participante está Confirmado no APP, mude o status para Pendente no BeInvited!", "Alerta BRSVP", "timeout=60");
			}
		}	
	}
	
} else {
	$part_nome_substituto  = '';
	$part_cod_substituto  = '';
	$guarda_cod_substituto  = '';
}


$modificado_part_cpf = $this->part_cpf;
