            $searchOk = true;
        }
        elseif ($field == $this->nmgp_fast_search && in_array($field, array("participante_id", "part_cpf_mestre", "part_cpf", "part_ativo", "part_tipo", "part_sexo", "enviar_app", "part_nome_cracha", "part_id_evento", "part_id_evento_publico", "part_id_evento_regional", "part_tipo_pessoa", "part_dt_nasc", "part_filiacao", "estrangeiro", "part_substituido", "part_empresa", "part_departamento", "part_cargo", "part_grupo", "part_clube", "dsc_empresa_rsvp", "cod_empresa_rsvp", "part_cep", "part_logradouro", "part_numero", "part_complemento", "part_bairro", "part_cidade", "part_uf", "part_ddd_01", "part_fone_01", "part_ddd_celular_01", "part_celeular_01", "codigo_telefone_internacional", "part_fone_internacional", "part_rg", "part_passaporte", "emissao_passaporte", "part_validade_pass", "part_passaporte_estrangeiro", "part_cpf_informado", "part_nacionalidade", "part_vacina_fa", "validade_visto", "numero_visto", "part_visto", "part_tam_camisa", "part_tam_calcado", "part_idioma", "idioma_preferido", "part_pais", "pais", "part_destaque_negrito", "part_fumante", "part_restricao_alimentar", "restricao_mobilidade", "part_cv_obs", "uid_pulseira_nfc", "roles_app", "id_evento_app", "external_id", "id_participante_app", "external_status", "part_email", "part_nome_secretaria", "part_email_secretaria", "part_cod_substituido", "part_nome_substituido"))) {
            $searchOk = true;
        }

        if (!$searchOk || '' == $this->nmgp_arg_fast_search) {
            return;
        }

        $htmlIni = '<div class="highlight" style="background-color: #fafaca; display: inline-block">';
        $htmlFim = '</div>';

        if ('qp' == $this->nmgp_cond_fast_search) {
            $keywords = preg_quote($this->nmgp_arg_fast_search, '/');
            $result = preg_replace('/'. $keywords .'/i', $htmlIni . '$0' . $htmlFim, $result);
        } elseif ('eq' == $this->nmgp_cond_fast_search) {
            if (strcasecmp($this->nmgp_arg_fast_search, $value) == 0) {
                $result = $htmlIni. $result .$htmlFim;
            }
        }
    }


