    function scGetColumnOrderRule($fieldName, &$orderColName, &$orderColOrient, &$orderColRule)
    {
        $sortRule = 'nosort';
        if ($_SESSION['sc_session'][$this->Ini->sc_page]['form_acompanhantes_rsvp']['ordem_cmp'] == $fieldName) {
            $orderColName = $fieldName;
            if ($_SESSION['sc_session'][$this->Ini->sc_page]['form_acompanhantes_rsvp']['ordem_ord'] == " desc") {
                $orderColOrient = $nome_img = $this->Ini->Label_sort_desc;
                $orderColRule = $sortRule = 'desc';
            } else {
                $orderColOrient = $nome_img = $this->Ini->Label_sort_asc;
                $orderColRule = $sortRule = 'asc';
            }
        }
        return $sortRule;
    }

    function scGetColumnOrderIcon($fieldName, $sortRule)
    {        if ('desc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_desc . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } elseif ('asc' == $sortRule) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort_asc . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } elseif ('' != $this->Ini->Label_sort) {
            return "<img src=\"" . $this->Ini->path_img_global . "/" . $this->Ini->Label_sort . "\" class=\"sc-ui-img-order-column\" id=\"sc-id-img-order-" . $fieldName . "\" />";
        } else {
            return '';
        }
    }

    function scIsFieldNumeric($fieldName)
    {
        switch ($fieldName) {
            case "participante_id":
                return true;
            case "participante_id_mestre":
                return true;
            case "part_cod_usuario":
                return true;
            case "part_bloqueio_id":
                return true;
            default:
                return false;
        }
        return false;
    }

    function scGetDefaultFieldOrder($fieldName)
    {
        switch ($fieldName) {
            case "participante_id":
                return 'desc';
            case "part_id_evento":
                return 'desc';
            case "part_id_evento_publico":
                return 'desc';
            case "part_id_evento_regional":
                return 'desc';
            case "part_dt_nasc":
                return 'desc';
            case "emissao_passaporte":
                return 'desc';
            case "part_validade_pass":
                return 'desc';
            case "validade_visto":
                return 'desc';
            case "participante_id_mestre":
                return 'desc';
            case "part_cod_usuario":
                return 'desc';
            case "part_dt_cadastro":
                return 'desc';
            case "part_dt_alteracao":
                return 'desc';
            case "part_dt_alt_contato_rsvp":
                return 'desc';
            case "part_dt_alt_presenca":
                return 'desc';
            case "part_dt_solicit_especial":
                return 'desc';
            case "part_dt_programacao":
                return 'desc';
            case "part_dt_aereo":
                return 'desc';
            case "par_dt_hospedagem":
                return 'desc';
            case "part_dt_transfer":
                return 'desc';
            case "part_dt_opcionais":
                return 'desc';
            case "part_save_the_date":
                return 'desc';
            case "part_bloqueio_id":
                return 'desc';
            default:
                return 'asc';
        }
        return 'asc';
    }

}
